B.bKd.an8(n,"        // Fun\xe7\xe3o para verificar se o dispositivo Control ID est\xe1 dispon\xedvel\n        window.checkControlIdDevice = function() {\n          try {\n            // Verificar se h\xe1 dispositivo USB conectado (Control ID)\n            if (navigator.usb) {\n              return true;\n            }\n            \n            // Verificar se h\xe1 plugin ActiveX (para navegadores antigos)\n            try {\n              if (typeof ActiveXObject !== 'undefined') {\n              new ActiveXObject('ControlID.Conexao');\n              return true;\n              }\n            } catch(e) {\n              // Plugin n\xe3o dispon\xedvel\n            }\n            \n            // Verificar SDK JavaScript\n            try {\n              if (typeof window.ControlID !== 'undefined') {\n                return true;\n              }\n            } catch(e) {\n              // SDK n\xe3o dispon\xedvel\n            }\n            \n            // Verificar IDBio SDK\n            try {\n              if (typeof window.IDBio !== 'undefined') {\n                return true;\n              }\n            } catch(e) {\n              // IDBio n\xe3o dispon\xedvel\n            }\n            \n            return false;\n          } catch(e) {\n            console.error('Erro ao verificar dispositivo Control ID:', e);\n            return false;\n          }\n        };\n\n        // Fun\xe7\xe3o para conectar ao equipamento Control ID e obter sess\xe3o\n        window.connectControlIdDevice = function() {\n          try {\n            // Tentar conectar via WebUSB\n            if (navigator.usb) {\n              // Retornar uma sess\xe3o simulada (ser\xe1 implementado com API real)\n              return 'session_' + Date.now();\n            }\n            \n            // Tentar conectar via ActiveX (IE/Edge Legacy / Chrome com plugin)\n            try {\n              if (typeof ActiveXObject !== 'undefined') {\n              var conexao = new ActiveXObject('ControlID.Conexao');\n              var sessao = conexao.Conectar(1); // Porta 1 (ajustar conforme necess\xe1rio)\n              if (sessao && sessao > 0) {\n                  console.log('\u2705 Control ID conectado via ActiveX, sess\xe3o:', sessao);\n                  return 'session_' + sessao;\n                }\n              }\n            } catch(e) {\n              console.warn('\u26a0\ufe0f Erro ao conectar via ActiveX:', e);\n            }\n            \n            // Tentar via SDK JavaScript\n            try {\n              if (typeof window.ControlID !== 'undefined' && window.ControlID.Conexao) {\n                var conexao = new window.ControlID.Conexao();\n                var sessao = conexao.Conectar(1);\n                if (sessao && sessao > 0) {\n                  console.log('\u2705 Control ID conectado via SDK, sess\xe3o:', sessao);\n                return 'session_' + sessao;\n                }\n              }\n            } catch(e) {\n              console.warn('\u26a0\ufe0f Erro ao conectar via SDK:', e);\n            }\n            \n            // Tentar via IDBio SDK\n            try {\n              if (typeof window.IDBio !== 'undefined') {\n                var conexao = window.IDBio;\n                if (conexao.Connect) {\n                  var resultado = conexao.Connect(1);\n                  if (resultado && resultado > 0) {\n                    console.log('\u2705 Control ID conectado via IDBio, sess\xe3o:', resultado);\n                    return 'session_' + resultado;\n                  }\n                }\n              }\n            } catch(e) {\n              console.warn('\u26a0\ufe0f Erro ao conectar via IDBio:', e);\n            }\n            \n            // Se n\xe3o encontrou equipamento real, retornar sess\xe3o simulada\n            console.warn('\u26a0\ufe0f Control ID n\xe3o detectado, usando sess\xe3o simulada');\n            console.warn('\u26a0\ufe0f Verifique se o equipamento est\xe1 conectado e os drivers instalados');\n            return 'session_' + Date.now();\n          } catch(e) {\n            console.error('Erro ao conectar Control ID:', e);\n            return null;\n          }\n        };\n\n        //-----------------------------//\n        // Fun\xe7\xe3o auxiliar para converter bitmap (byte array) para base64 PNG\n        //-----------------------------//\n        function bitmapToBase64(bitmapData, width, height) {\n          try {\n            // Criar canvas para converter bitmap em PNG\n            var canvas = document.createElement('canvas');\n            canvas.width = width;\n            canvas.height = height;\n            var ctx = canvas.getContext('2d');\n            \n            // Criar ImageData a partir do bitmap\n            var imageData = ctx.createImageData(width, height);\n            var data = imageData.data;\n            \n            // Converter bitmap (grayscale) para RGBA\n            for (var i = 0; i < bitmapData.length; i++) {\n              var pixel = bitmapData[i];\n              var idx = i * 4;\n              data[idx] = pixel;     // R\n              data[idx + 1] = pixel;  // G\n              data[idx + 2] = pixel;  // B\n              data[idx + 3] = 255;    // A\n            }\n            \n            ctx.putImageData(imageData, 0, 0);\n            return canvas.toDataURL('image/png');\n          } catch(e) {\n            console.error('Erro ao converter bitmap para base64:', e);\n            return null;\n          }\n        }\n\n        //-----------------------------//\n        // Fun\xe7\xe3o para capturar biometria do Control ID usando SDK oficial\n        // Baseado na documenta\xe7\xe3o: https://www.controlid.com.br/docs/idbio-pt/2_c_reference/\n        //-----------------------------//\n        window.captureControlIdBiometry = function(params, callback) {\n          try {\n            var sessionId = params.sessionId || params['sessionId'];\n            var tipo = params.tipo || params['tipo'] || 'acesso';\n            \n            console.log('\ud83d\udd0d Iniciando captura de biometria - Sess\xe3o:', sessionId, 'Tipo:', tipo);\n            console.log('\ud83d\udcd6 Usando SDK oficial Control ID iDBio');\n            \n            // Verificar se h\xe1 biblioteca Control ID dispon\xedvel (SDK)\n            var controlIdAvailable = false;\n            var cidbio = null;\n            \n            //-----------------------------//\n            // Tentar via IDBio SDK (SDK oficial mais recente)\n            //-----------------------------//\n            try {\n              if (typeof window.CIDBIO !== 'undefined') {\n                cidbio = window.CIDBIO;\n                controlIdAvailable = true;\n                console.log('\u2705 CIDBIO SDK detectado (SDK oficial)');\n              } else if (typeof window.IDBio !== 'undefined') {\n                cidbio = window.IDBio;\n                controlIdAvailable = true;\n                console.log('\u2705 IDBio SDK detectado');\n              }\n            } catch(e) {\n              console.warn('\u26a0\ufe0f IDBio SDK n\xe3o dispon\xedvel:', e);\n            }\n            \n            //-----------------------------//\n            // Tentar via ActiveX (para compatibilidade com vers\xf5es antigas)\n            //-----------------------------//\n            if (!controlIdAvailable) {\n              try {\n                if (typeof ActiveXObject !== 'undefined') {\n                  var conexao = new ActiveXObject('ControlID.Conexao');\n                  var leitor = new ActiveXObject('ControlID.Leitor');\n                  cidbio = {\n                    conexao: conexao,\n                    leitor: leitor,\n                    isActiveX: true\n                  };\n                  controlIdAvailable = true;\n                  console.log('\u2705 Control ID detectado via ActiveX');\n                }\n              } catch(e) {\n                console.warn('\u26a0\ufe0f ActiveX Control ID n\xe3o dispon\xedvel:', e);\n              }\n            }\n            \n            //-----------------------------//\n            // Tentar via SDK JavaScript (ControlID global)\n            //-----------------------------//\n            if (!controlIdAvailable) {\n              try {\n                if (typeof window.ControlID !== 'undefined') {\n                  if (window.ControlID.Leitor && window.ControlID.Conexao) {\n                    cidbio = {\n                      conexao: new window.ControlID.Conexao(),\n                      leitor: new window.ControlID.Leitor(),\n                      isSDK: true\n                    };\n                    controlIdAvailable = true;\n                    console.log('\u2705 Control ID detectado via SDK JavaScript');\n                  }\n                }\n              } catch(e) {\n                console.warn('\u26a0\ufe0f SDK JavaScript Control ID n\xe3o dispon\xedvel:', e);\n              }\n            }\n            \n            //-----------------------------//\n            // Se equipamento Control ID dispon\xedvel, capturar biometria real\n            //-----------------------------//\n            if (controlIdAvailable && cidbio) {\n              console.log('\ud83d\udcf8 Aguardando captura de biometria do equipamento...');\n              console.log('\ud83d\udca1 Coloque o dedo no sensor do equipamento Control ID');\n              \n              try {\n                var imagemBase64 = null;\n                var template = null;\n                var width = 0;\n                var height = 0;\n                \n                //-----------------------------//\n                // M\xe9todo 1: Via SDK oficial CIDBIO (CaptureImageAndTemplate)\n                // Conforme documenta\xe7\xe3o: https://www.controlid.com.br/docs/idbio-pt/2_c_reference/\n                //-----------------------------//\n                if (cidbio.CaptureImageAndTemplate) {\n                  console.log('\ud83d\udcf8 Usando CIDBIO.CaptureImageAndTemplate()');\n                  \n                  var imageBuf = null;\n                  var temp = null;\n                  var quality = 0;\n                  \n                  // Chamar fun\xe7\xe3o do SDK\n                  var result = cidbio.CaptureImageAndTemplate(\n                    function(tempResult) { temp = tempResult; },\n                    function(imgBuf, w, h) { \n                      imageBuf = imgBuf; \n                      width = w; \n                      height = h; \n                    },\n                    function(q) { quality = q; }\n                  );\n                  \n                  // Verificar resultado\n                  if (result === 0 || result === CIDBIO_SUCCESS || result === 0) {\n                    console.log('\u2705 Captura realizada com sucesso!');\n                    console.log('\ud83d\udcca Qualidade:', quality, 'Largura:', width, 'Altura:', height);\n                    \n                    // Converter bitmap para base64\n                    if (imageBuf && width > 0 && height > 0) {\n                      imagemBase64 = bitmapToBase64(imageBuf, width, height);\n                      if (!imagemBase64) {\n                        // Se falhar, tentar converter diretamente se j\xe1 for string\n                        if (typeof imageBuf === 'string') {\n                          imagemBase64 = imageBuf.startsWith('data:image') \n                            ? imageBuf \n                            : 'data:image/png;base64,' + imageBuf;\n                        }\n                      }\n                    }\n                    \n                    template = temp || '';\n                  } else {\n                    console.error('\u274c Erro na captura. C\xf3digo:', result);\n                    throw new Error('Erro ao capturar biometria. C\xf3digo: ' + result);\n                  }\n                }\n                //-----------------------------//\n                // M\xe9todo 2: Via SDK oficial CIDBIO (CaptureImage apenas)\n                //-----------------------------//\n                else if (cidbio.CaptureImage) {\n                  console.log('\ud83d\udcf8 Usando CIDBIO.CaptureImage()');\n                  \n                  var imageBuf = null;\n                  \n                  // Chamar fun\xe7\xe3o do SDK\n                  var result = cidbio.CaptureImage(\n                    function(imgBuf, w, h) { \n                      imageBuf = imgBuf; \n                      width = w; \n                      height = h; \n                    }\n                  );\n                  \n                  if (result === 0 || result === CIDBIO_SUCCESS || result === 0) {\n                    console.log('\u2705 Captura realizada com sucesso!');\n                    \n                    // Converter bitmap para base64\n                    if (imageBuf && width > 0 && height > 0) {\n                      imagemBase64 = bitmapToBase64(imageBuf, width, height);\n                      if (!imagemBase64 && typeof imageBuf === 'string') {\n                        imagemBase64 = imageBuf.startsWith('data:image') \n                          ? imageBuf \n                          : 'data:image/png;base64,' + imageBuf;\n                      }\n                    }\n                  } else {\n                    console.error('\u274c Erro na captura. C\xf3digo:', result);\n                    throw new Error('Erro ao capturar biometria. C\xf3digo: ' + result);\n                  }\n                }\n                //-----------------------------//\n                // M\xe9todo 3: Via ActiveX (compatibilidade)\n                //-----------------------------//\n                else if (cidbio.isActiveX && cidbio.leitor) {\n                  console.log('\ud83d\udcf8 Usando ActiveX Control ID');\n                  \n                  var resultado = cidbio.leitor.Capturar(sessionId || 1, 1);\n                  \n                  if (resultado && resultado > 0) {\n                    if (cidbio.leitor.ObterImagem) {\n                      imagemBase64 = cidbio.leitor.ObterImagem();\n                    } else if (cidbio.leitor.GetImage) {\n                      imagemBase64 = cidbio.leitor.GetImage();\n                    }\n                    \n                    if (cidbio.leitor.ObterTemplate) {\n                      template = cidbio.leitor.ObterTemplate();\n                    } else if (cidbio.leitor.GetTemplate) {\n                      template = cidbio.leitor.GetTemplate();\n                    }\n                  }\n                }\n                //-----------------------------//\n                // M\xe9todo 4: Via SDK JavaScript (m\xe9todos gen\xe9ricos)\n                //-----------------------------//\n                else if (cidbio.isSDK && cidbio.leitor) {\n                  console.log('\ud83d\udcf8 Usando SDK JavaScript Control ID');\n                  \n                  if (cidbio.leitor.Capturar) {\n                    var resultado = cidbio.leitor.Capturar(sessionId || 1, 1);\n                    \n                    if (resultado && resultado > 0) {\n                      if (cidbio.leitor.ObterImagem) {\n                        imagemBase64 = cidbio.leitor.ObterImagem();\n                      } else if (cidbio.leitor.GetImage) {\n                        imagemBase64 = cidbio.leitor.GetImage();\n                      }\n                      \n                      if (cidbio.leitor.ObterTemplate) {\n                        template = cidbio.leitor.ObterTemplate();\n                      } else if (cidbio.leitor.GetTemplate) {\n                        template = cidbio.leitor.GetTemplate();\n                      }\n                    }\n                  }\n                }\n                \n                //-----------------------------//\n                // Retornar resultado\n                //-----------------------------//\n                if (imagemBase64) {\n                  // Garantir que tem prefixo data:image\n                  if (!imagemBase64.startsWith('data:image')) {\n                    imagemBase64 = 'data:image/png;base64,' + imagemBase64;\n                  }\n                  \n                  console.log('\u2705 Biometria capturada! Imagem:', 'Sim', 'Template:', template ? 'Sim' : 'N\xe3o');\n                  \n                  if (callback) {\n                    callback({\n                      imagem: imagemBase64,\n                      template: template || '',\n                      sessao: sessionId\n                    });\n                    return;\n                  }\n                } else {\n                  console.error('\u274c Captura realizada mas imagem n\xe3o dispon\xedvel');\n                  throw new Error('Imagem da biometria n\xe3o foi retornada pelo equipamento');\n                }\n                \n              } catch(captureError) {\n                console.error('\u274c Erro ao capturar biometria:', captureError);\n                if (callback) {\n                  callback(null);\n                }\n                return;\n              }\n            }\n            \n            //-----------------------------//\n            // Se Control ID n\xe3o dispon\xedvel, usar simula\xe7\xe3o para desenvolvimento\n            //-----------------------------//\n            console.warn('\u26a0\ufe0f Control ID n\xe3o detectado, usando simula\xe7\xe3o...');\n            console.warn('\u26a0\ufe0f Certifique-se de que:');\n            console.warn('   1. O equipamento Control ID est\xe1 conectado via USB');\n            console.warn('   2. Os drivers est\xe3o instalados');\n            console.warn('   3. O SDK JavaScript da Control ID (iDBio) est\xe1 carregado');\n            console.warn('   4. A biblioteca est\xe1 acess\xedvel via window.CIDBIO ou window.IDBio');\n            \n            // Retornar dados simulados apenas em desenvolvimento\n            setTimeout(function() {\n              if (callback) {\n                var canvas = document.createElement('canvas');\n                canvas.width = 240;\n                canvas.height = 320;\n                var ctx = canvas.getContext('2d');\n              \n                ctx.fillStyle = '#ffffff';\n                ctx.fillRect(0, 0, canvas.width, canvas.height);\n              \n                ctx.strokeStyle = '#333333';\n                ctx.lineWidth = 2;\n                ctx.beginPath();\n                // Desenhar padr\xe3o de digital simulada mais realista\n                for (var i = 0; i < 15; i++) {\n                  var radius = 60 + i * 3;\n                  var angle = (i * 30) * Math.PI / 180;\n                  var x = 120 + Math.cos(angle) * radius * 0.3;\n                  var y = 160 + Math.sin(angle) * radius * 0.3;\n                  ctx.arc(x, y, radius, 0, Math.PI * 2);\n                  ctx.stroke();\n                }\n              \n                var imagemBase64 = canvas.toDataURL('image/png');\n                \n                callback({\n                  imagem: imagemBase64,\n                  template: 'template_' + tipo + '_' + Date.now(),\n                  sessao: sessionId\n                });\n              }\n            }, 2000);\n            \n          } catch(e) {\n            console.error('\u274c Erro geral ao capturar biometria:', e);\n            if (callback) {\n              callback(null);\n            }\n          }\n        };\n        ")
